<label>Title<input name="title" maxlength="255" value="{{ $course->title ?? '' }}" required></label><label>Description<textarea name="description" maxlength="10000">{{ $course->description ?? '' }}</textarea></label><label>Provider<input name="provider" maxlength="255" value="{{ $course->provider ?? '' }}"></label><label>Course URL (optional)<input type="url" name="delivery_url" value="{{ $course->delivery_url ?? '' }}"></label><label>Status<select name="active"><option value="1" @selected($course?->active ?? true)>Active</option><option value="0" @selected($course && !$course->active)>Inactive</option></select></label>
